import React from 'react';
import { AlgorithmResult } from '../types';

interface Props {
  dijkstraResult: AlgorithmResult | null;
  astarResult: AlgorithmResult | null;
}

const ResultCard: React.FC<{ title: string; result: AlgorithmResult | null }> = ({ title, result }) => (
  <div className="result-card">
    <h3>{title}</h3>
    {result ? (
      <>
        <p><strong>Path:</strong> {result.path.join(' → ') || 'No path found'}</p>
        <p><strong>Est. Time:</strong> {result.totalTime === Infinity ? '∞' : result.totalTime.toFixed(2)} mins</p>
        <p><strong>Nodes Explored:</strong> {result.nodesExplored}</p>
        <p><strong>Exec Time:</strong> {result.executionTime.toFixed(4)} ms</p>
      </>
    ) : (
      <p>Run algorithm to see results.</p>
    )}
  </div>
);

const ResultPanel: React.FC<Props> = ({ dijkstraResult, astarResult }) => {
  return (
    <div style={{ display: 'flex', gap: '20px', marginTop: '20px' }}>
      <div style={{ flex: 1 }}>
        <ResultCard title="🛣️ Dijkstra Result" result={dijkstraResult} />
      </div>
      <div style={{ flex: 1 }}>
        <ResultCard title="⭐ A* Result" result={astarResult} />
      </div>
    </div>
  );
};

export default ResultPanel;
